class ActiveImageProcessor {
  private queue: Array<{ image: Image; resolve: (r: Image) => void }> = [];

  constructor() {
    this.startWorker(); // runs on its own thread/worker
  }

  applyFilter(image: Image): Promise<Image> {
    return new Promise((resolve) => {
      this.queue.push({ image, resolve }); // returns instantly
    });
  }

  private async startWorker() {
    while (true) {
      const request = this.queue.shift();
      if (request) {
        const result = runExpensiveFilter(request.image);
        request.resolve(result);
      }
      await yieldToEventLoop();
    }
  }
}

